private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder must not be null");
    }
    // Ensure the index is within bounds
    int startPos = Math.max(0, Math.min(i, bb.limit()));
    bb.position(startPos);
    while (bb.hasRemaining()) {
        int byte1 = bb.get() & 0xFF;
        // Stop on null terminator if present
        if (byte1 == 0x00) {
            break;
        }
        char[] outChars;
        try {
            if (byte1 < 0x80) {
                // 1-byte sequence
                outChars = new char[]{(char) byte1};
            } else if ((byte1 >> 5) == 0x6) {
                // 2-byte sequence
                if (!bb.hasRemaining()) break;
                int byte2 = bb.get() & 0x3F;
                int codepoint = ((byte1 & 0x1F) << 6) | byte2;
                if (codepoint >= 0x80) {
                    outChars = Character.toChars(codepoint);
                } else {
                    // Overlong encoding, use replacement
                    outChars = new char[]{(char) 0xFFFD};
                }
            } else if ((byte1 >> 4) == 0xE) {
                // 3-byte sequence
                if (bb.remaining() < 2) break;
                int byte2 = bb.get() & 0x3F;
                int byte3 = bb.get() & 0x3F;
                int codepoint = ((byte1 & 0x0F) << 12) | (byte2 << 6) | byte3;
                outChars = Character.toChars(codepoint);
            } else if ((byte1 >> 3) == 0x1E) {
                // 4-byte sequence
                if (bb.remaining() < 3) break;
                int byte2 = bb.get() & 0x3F;
                int byte3 = bb.get() & 0x3F;
                int byte4 = bb.get() & 0x3F;
                int codepoint = ((byte1 & 0x07) << 18) | (byte2 << 12) | (byte3 << 6) | byte4;
                outChars = Character.toChars(codepoint);
            } else {
                // Invalid leading byte, use replacement character
                outChars = new char[]{(char) 0xFFFD};
            }
        } catch (IllegalArgumentException | IndexOutOfBoundsException e) {
            // Any failure in decoding results in the Unicode replacement char
            outChars = new char[]{(char) 0xFFFD};
        }
        sb.append(outChars);
    }
    // Return the position after the processed bytes
    return bb.position();
}

int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Validate input parameters
    if (offset < 0) {
        throw new IllegalArgumentException("offset must be non-negative, got: " + offset);
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("numLocal must be non-negative, got: " + numLocal);
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("numStack must be non-negative, got: " + numStack);
    }

    try {
        // Allocate a new array large enough to hold the frame header
        // and all local and stack entries that will be written later.
        final int initialSize = 3 + numLocal + numStack; // 3 header slots + locals + stack
        currentFrame = new int[initialSize];
        // Store the frame header values
        currentFrame[0] = offset;
        currentFrame[1] = numLocal;
        currentFrame[2] = numStack;
        // Return the index of the next slot to be populated
        return 3;
    } catch (Throwable t) {
        // Wrap any unexpected exception into a runtime exception so the caller knows something went
        // wrong during frame setup. This protects against array allocation failure, etc.
        throw new RuntimeException("Unable to start new stack map frame", t);
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    // Prevent integer overflow when calculating the new capacity
    if (buf.length > Integer.MAX_VALUE - size) {
        throw new RuntimeException("Cannot enlarge byte vector: desired size exceeds Integer.MAX_VALUE");
    }
    int newLength = buf.length + size;
    try {
        byte[] newBuf = new byte[newLength];
        System.arraycopy(buf, 0, newBuf, 0, buf.length);
        buf = newBuf;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Failed to allocate enlarged byte vector", e);
    }
}

