public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Validate input
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    try {
        // Create a vertex mapping that maps each vertex to itself
        Map<V, V> vertexMapping = new HashMap<>();
        for (V v : graph.getVertices()) {
            vertexMapping.put(v, v);
        }
        // The IsomorphicGraphMapping class is assumed to have a constructor that
        // accepts the source graph, the target graph, and a vertex mapping.
        // The edge mapping will be inferred automatically by using the vertex
        // mapping (identity mapping) for edges.
        return new IsomorphicGraphMapping<>(graph, graph, vertexMapping);
    } catch (Exception e) {
        // Wrap any runtime exceptions in an unchecked exception
        throw new RuntimeException("Failed to create identity mapping for the graph", e);
    }
}

