private static void registerDeleteOnExit(File f) throws IOException {
    if (!f.exists()) {
        return;
    }
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children == null) {
            throw new IOException("Failed to list contents of directory: " + f);
        }
        for (File child : children) {
            registerDeleteOnExit(child);
        }
    }
    f.deleteOnExit();
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph must not be null.");
    }
    if (resultMap == null || resultMap.isEmpty()) {
        return; // nothing to graph
    }

    // Collect vertices from the map
    List<V> vertices = new ArrayList<>(resultMap.values());
    int size = vertices.size();
    if (size < 2) {
        // With less than two vertices we cannot create bipartite edges
        return;
    }

    // Define bipartite partitions: first half to left, second half to right
    int midpoint = size / 2;
    List<V> leftPartition = vertices.subList(0, midpoint);
    List<V> rightPartition = vertices.subList(midpoint, size);

    // Add all vertices to the target graph
    for (V v : vertices) {
        try {
            target.addVertex(v);
        } catch (Exception e) {
            // Ignore duplicate vertex addition or unsupported operations
        }
    }

    // Connect every left vertex to every right vertex
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            try {
                target.addEdge(leftVertex, rightVertex);
            } catch (Exception e) {
                // Edge might already exist or the graph does not support this operation
                // We ignore such exceptions to keep the method robust
            }
        }
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer is available
    if (buffer == null) {
        return -1;
    }

    // Normalize starting position
    if (pos < 0) {
        pos = 0;
    }

    int length = buffer.length;
    if (pos >= length) {
        return -1;
    }

    // Search for the byte value
    for (int i = pos; i < length; i++) {
        if (buffer[i] == value) {
            return i; // Return index relative to start of buffer
        }
    }

    // Not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("out");
    }
    if (message == null) {
        throw new NullPointerException("message");
    }
    if (schema == null) {
        throw new NullPointerException("schema");
    }
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }
    // Compute the serialized size of the message
    int size = schema.computeSize(message);
    // Write the size prefix (as a varint) to the output stream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Serialize the message into the output stream using the schema
    schema.writeTo(cos, message);
    cos.flush();
    return size;
}

