public static void createConfigurationDirectory() {
    String dirPath;
    String os = System.getProperty("os.name");
    if (os != null && os.contains("Windows 2000")) {
        // Attempt to use the system drive environment variable
        String systemDrive = System.getenv("SYSTEMDRIVE");
        if (systemDrive == null) {
            systemDrive = "C:\\";
        }
        // Ensure backslash at the end
        if (!systemDrive.endsWith("\\")) {
            systemDrive += "\\";
        }
        dirPath = systemDrive + "Documents and Settings" + File.separator + "lf5";
    } else {
        String userHome = System.getProperty("user.home");
        if (userHome == null || userHome.isEmpty()) {
            // Fallback to root directory if user.home is not available
            userHome = System.getProperty("java.io.tmpdir", ".")
                           .replace("\\", File.separator);
        }
        dirPath = userHome + File.separator + "lf5";
    }

    File dir = new File(dirPath);
    if (!dir.exists()) {
        try {
            boolean created = dir.mkdirs();
            if (!created && !dir.exists()) {
                throw new RuntimeException("Failed to create directory: " + dirPath);
            }
        } catch (SecurityException se) {
            throw new RuntimeException("Permission denied while creating directory: " + dirPath, se);
        }
    }
}

public long readLong(final int offset) {
    if (offset < 0 || offset + 8 > this.data.length) {
        throw new IllegalArgumentException("Offset out of bounds: " + offset);
    }
    long value = ((long) (this.data[offset]     & 0xFF) << 56)
               | ((long) (this.data[offset + 1] & 0xFF) << 48)
               | ((long) (this.data[offset + 2] & 0xFF) << 40)
               | ((long) (this.data[offset + 3] & 0xFF) << 32)
               | ((long) (this.data[offset + 4] & 0xFF) << 24)
               | ((long) (this.data[offset + 5] & 0xFF) << 16)
               | ((long) (this.data[offset + 6] & 0xFF) << 8)
               | ((long) (this.data[offset + 7] & 0xFF));
    return value;
}

public boolean equals(final byte[] data, int offset, final int len){
    // Validate input parameters
    if (data == null || bytes == null) {
        return false;
    }
    if (len <= 0 || offset < 0) {
        return false;
    }
    if (offset + len > data.length) {
        return false;
    }
    // Lengths must match
    if (len != bytes.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < len; i++) {
        if (data[offset + i] != bytes[i]) {
            return false;
        }
    }
    return true;
}

