public synchronized void send(final String message) {
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }

    if (clientWriters == null) {
        return; // nothing to send to
    }

    Iterator<PrintWriter> it = clientWriters.iterator();
    while (it.hasNext()) {
        PrintWriter pw = it.next();
        if (pw == null) {
            it.remove();
            continue;
        }
        try {
            pw.write(message);
            pw.write("\r\n");      // Telnet line ending
            pw.flush();
        } catch (IOException e) {
            // Remove unusable writer
            it.remove();
            try {
                pw.close();
            } catch (IOException ignored) {
            }
        }
    }
}

