            long rangeEnd = current + FETCH_DATA_DURATION - 1;
            // Handle potential overflow
            if (rangeEnd < 0 || rangeEnd > end) {
                rangeEnd = end;
            }
            ranges.add(new TimeRange(current, rangeEnd));
            current = rangeEnd + 1;
        }
    } catch (RuntimeException e) {
        // In case TimeRange constructor or other operations throw an exception,
        // return an empty list to avoid propagating the error.
        return new ArrayList<>();
    }
    return ranges;
}

