static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    // Basic range check for an 8-digit date in the form YYYYMMDD
    if(timeBucket < 10000101L || timeBucket > 99991231L){
        throw new IllegalArgumentException("timeBucket is not a valid 8-digit date");
    }
    int year  = (int)(timeBucket / 10000);
    int monthDay = (int)(timeBucket % 10000);
    int month = monthDay / 100;
    int day   = monthDay % 100;
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("month must be between 01 and 12");
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("day must be between 01 and 31");
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non‑negative");
    }
    if (index > str.length() - len) {
        throw new IllegalArgumentException("Index + length exceeds string bounds");
    }
    int byteCount = 0;
    try {
        int end = index + len;
        int i = index;
        while (i < end) {
            char c = str.charAt(i);
            if (c <= 0x007F) {
                byteCount += 1;
            } else if (c <= 0x07FF) {
                byteCount += 2;
            } else if (Character.isHighSurrogate(c)) {
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    // Valid surrogate pair => U+10000 to U+10FFFF
                    byteCount += 4;
                    i++; // Skip the low surrogate
                } else {
                    // Unmatched high surrogate; treat as 3 bytes (ISO-10646 UTF‑8)
                    byteCount += 3;
                }
            } else if (Character.isLowSurrogate(c)) {
                // Unmatched low surrogate; treat as 3 bytes
                byteCount += 3;
            } else {
                byteCount += 3;
            }
            i++;
        }
    } catch (Exception e) {
        // Unexpected runtime error; wrap and rethrow as unchecked exception
        throw new RuntimeException("Error computing UTF‑8 size", e);
    }
    return byteCount;
}

