public static String sub(String str, int start, int end) {
    if (str == null) {
        return null;
    }
    int len = str.length();

    // Normalize start index
    if (start < 0) {
        start = 0;
    }
    if (start > len) {
        start = len; // will result in empty string
    }

    // Normalize end index
    if (end < start) {
        return "";
    }
    if (end > len) {
        end = len;
    }

    return str.substring(start, end);
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative: " + byteLength);
    }

    // If null array, just increase position (filling with 0s implicitly)
    if (byteArrayValue == null) {
        // Ensure capacity
        int newPos = this.pos + byteLength;
        if (newPos > this.data.length) {
            int newSize = Math.max(this.data.length << 1, newPos);
            byte[] newData = new byte[newSize];
            System.arraycopy(this.data, 0, newData, 0, this.pos);
            this.data = newData;
        }
        this.pos = newPos;
        return this;
    }

    // Validate offset boundaries
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new ArrayIndexOutOfBoundsException("byteOffset out of bounds: " + byteOffset);
    }
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new ArrayIndexOutOfBoundsException(
            "byteLength extends beyond array bounds: byteOffset=" + byteOffset +
            ", byteLength=" + byteLength + ", arrayLength=" + byteArrayValue.length);
    }

    // Ensure capacity
    int newPos = this.pos + byteLength;
    if (newPos > this.data.length) {
        int newSize = Math.max(this.data.length << 1, newPos);
        byte[] newData = new byte[newSize];
        System.arraycopy(this.data, 0, newData, 0, this.pos);
        this.data = newData;
    }

    // Copy bytes
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.pos, byteLength);
    this.pos = newPos;
    return this;
}

