public void removeFromTreeEdgeList() {
    try {
        // Remove from the source vertex list
        if (prevInSource != null) {
            prevInSource.nextInSource = nextInSource;
        } else if (source != null) {
            source.firstTreeEdge = nextInSource;
        }
        if (nextInSource != null) {
            nextInSource.prevInSource = prevInSource;
        }

        // Remove from the target vertex list
        if (prevInTarget != null) {
            prevInTarget.nextInTarget = nextInTarget;
        } else if (target != null) {
            target.firstTreeEdge = nextInTarget;
        }
        if (nextInTarget != null) {
            nextInTarget.prevInTarget = prevInTarget;
        }

        // Null out this edge references to help GC
        prevInSource = prevInTarget = null;
        nextInSource = nextInTarget = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove edge from tree edge lists", e);
    }
}

