private static String substitute(String value, java.util.Properties props, int depth) throws Exception {
    if (depth > 10) {
        throw new RuntimeException("Too many substitution levels");
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    java.lang.StringBuffer sb = new java.lang.StringBuffer();
    while (matcher.find()) {
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = "";
        } else {
            replacement = substitute(replacement, props, depth + 1);
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

