private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Return true only when both are null, otherwise false if just one is null
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }

    final int suffixLen = suffix.length();
    final int strLen = str.length();

    // If suffix is longer than str, it cannot match
    if (suffixLen > strLen) {
        return false;
    }

    // If ignoreCase is requested, use regionMatches to compare the ending region
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    String[] rawSegments = rawPath.split("/");
    for (String seg : rawSegments) {
        if (seg.isEmpty()) {
            // Skip leading slash or consecutive slashes
            continue;
        }
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is always supported, rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

