    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    try {
        double x = box.getX();
        double y = box.getY();
        double width = box.getWidth();
        double height = box.getHeight();

        double halfWidth = width / 2.0;
        Box2D left = new Box2D(x, y, halfWidth, height);
        Box2D right = new Box2D(x + halfWidth, y, halfWidth, height);

        return new Pair<>(left, right);
    } catch (Exception e) {
        throw new RuntimeException("Failed to split box along X axis", e);
    }
}

