public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0;
    }

    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        try {
            // The LinkedBuffer is expected to expose its internal buffer and the number of
            // valid bytes currently stored.
            byte[] buf = current.getBuffer();
            int len = current.getSize();
            if (buf != null && len > 0) {
                out.write(buf, 0, len);
                totalSize += len;
            }
            current = current.getNextBuffer();
        } catch (NullPointerException e) {
            // If we encounter a null reference while traversing the buffers, abort and
            // rethrow as a more informative exception.
            throw new IOException("Failed to traverse LinkedBuffer chain due to null reference", e);
        }
    }
    return totalSize;
}

