    if (event == null) {
        return "";
    }
    try {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        // Append timestamp
        sb.append("[");
        sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                .format(new java.util.Date(event.getTimeStamp())));
        sb.append("] ");
        // Append level
        sb.append("[");
        sb.append(event.getLevel());
        sb.append("] ");
        // Append logger name
        sb.append(event.getLoggerName());
        sb.append(" - ");
        // Append formatted message
        sb.append(event.getFormattedMessage());
        // Append thread name
        sb.append(" (Thread: ");
        sb.append(event.getThreadName());
        sb.append(")");
        // Append throwable information if present
        if (event.getThrowableInformation() != null) {
            sb.append(System.lineSeparator());
            java.lang.Throwable t = event.getThrowableInformation().getThrowable();
            sb.append(t.toString());
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            t.printStackTrace(pw);
            sb.append(sw.toString());
        }
        return sb.toString();
    } catch (Throwable t) {
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        t.printStackTrace(pw);
        return "Error formatting LoggingEvent: " + sw.toString();
    }
}

