@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or primitive char
    if (Character.class != type && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char, but was " + type);
    }

    // Null handling
    if (value == null) {
        if (type != Character.class) {
            // Primitive char cannot be null
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null; // Return null for Character
    }

    try {
        // Already a Character
        if (value instanceof Character) {
            return value;
        }

        // String of length 1
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new IllegalArgumentException("String length must be 1 to convert to Character");
            }
        }

        // Number converted via int value
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return (char) intVal;
        }

        // Fallback: use toString() of the value and check length
        String text = value.toString();
        if (text.length() == 1) {
            return text.charAt(0);
        }

        throw new IllegalArgumentException("Cannot convert value of type " + value.getClass() + " to Character");
    } catch (Exception e) {
        // Wrap any runtime exception into the expected Exception
        throw new Exception("Conversion failed: " + e.getMessage(), e);
    }
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null) {
        return false;
    }
    if (searchStrArray.isEmpty()) {
        return false;
    }

    String lowerStr = str.toLowerCase(Locale.ROOT);

    for (String searchStr : searchStrArray) {
        if (searchStr == null || searchStr.isEmpty()) {
            continue;
        }
        String lowerSearch = searchStr.toLowerCase(Locale.ROOT);
        for (int i = 0; i < lowerSearch.length(); i++) {
            if (lowerStr.indexOf(lowerSearch.charAt(i)) >= 0) {
                return true;
            }
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start with the next odd number >= desiredCapacity
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    int bound = desiredCapacity;
    if (desiredCapacity >= 1000) {
        // 11% above desiredCapacity
        bound = (int) (desiredCapacity * 111L / 100);
    }

    // Search within the bound first
    for (int n = candidate; n <= bound; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }

    // If no prime found within the bound, continue searching beyond it
    for (int n = bound + 1; ; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrt; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

