public static Object findFirstMatch(Collection source, Collection candidates) {
    if (source == null) {
        throw new IllegalArgumentException("Source collection cannot be null");
    }
    if (candidates == null) {
        throw new IllegalArgumentException("Candidates collection cannot be null");
    }
    // If either collection is empty, return null immediately
    if (source.isEmpty() || candidates.isEmpty()) {
        return null;
    }

    for (Object candidate : candidates) {
        try {
            if (source.contains(candidate)) {
                return candidate;
            }
        } catch (Exception e) {
            // If source.contains throws a runtime exception, propagate it
            // so the caller is aware that the operation failed
            throw e;
        }
    }
    return null;
}

