public final byte[] toByteArray() {
    try {
        // Attempt to use a byte array and count fields similar to ByteArrayOutputStream
        java.lang.reflect.Field bufField = this.getClass().getDeclaredField("buf");
        java.lang.reflect.Field countField = this.getClass().getDeclaredField("count");
        bufField.setAccessible(true);
        countField.setAccessible(true);
        byte[] buf = (byte[]) bufField.get(this);
        int count = countField.getInt(this);
        if (buf == null || count <= 0) {
            return new byte[0];
        }
        if (count > buf.length) {
            count = buf.length;
        }
        return java.util.Arrays.copyOf(buf, count);
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // Fallback: look for a List<byte[]> field that holds segments
        try {
            java.lang.reflect.Field listField = this.getClass().getDeclaredField("buffers");
            listField.setAccessible(true);
            java.util.List<byte[]> list = (java.util.List<byte[]>) listField.get(this);
            if (list == null || list.isEmpty()) {
                return new byte[0];
            }
            java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
            for (byte[] segment : list) {
                if (segment != null) {
                    out.write(segment);
                }
            }
            return out.toByteArray();
        } catch (Exception ignored) {
            // If anything fails, fall through to return empty array
        }
    }
    // If all reflection attempts fail, return an empty array safely
    return new byte[0];
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int length = str.length();
    for (int i = 0; i < length; ) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 2;
                    break;
                case 'u':
                    // Unicode escape must be followed by exactly four hex digits
                    if (i + 6 > length) {
                        throw new Exception("Incomplete Unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    int codePoint;
                    try {
                        codePoint = Integer.parseInt(hex, 16);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                    }
                    sb.append((char) codePoint);
                    i += 6;
                    break;
                default:
                    // Unknown escape sequence; treat the backslash as literal
                    sb.append('\\');
                    sb.append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

