final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // The index refers to the tag byte of the CONSTANT_Utf8 entry.
    int offset = constantPoolEntryIndex + 1; // skip tag
    if (offset + 1 >= classFileBuffer.length) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of range");
    }
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
    if (offset + 2 + length > classFileBuffer.length) {
        throw new IllegalArgumentException("Utf8 entry truncated in class file");
    }
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small for Utf8 entry");
    }
    try {
        java.nio.ByteBuffer src = java.nio.ByteBuffer.wrap(classFileBuffer, offset + 2, length);
        java.nio.CharBuffer dst = java.nio.CharBuffer.wrap(charBuffer, 0);
        java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
        decoder.decode(src, dst, true);
        int decodedLength = dst.position();
        // No need to clear dst now; we just use the decoded characters.
        return new java.lang.String(charBuffer, 0, decodedLength);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new RuntimeException("Failed to decode CONSTANT_Utf8 entry", e);
    }
}

private static char decodeHexNibble(final char c){
    // Handle numeric digits '0' - '9'
    if (c >= '0' && c <= '9') {
        return (char)(c - '0');
    }
    // Handle lowercase hex letters 'a' - 'f'
    if (c >= 'a' && c <= 'f') {
        return (char)(c - 'a' + 10);
    }
    // Handle uppercase hex letters 'A' - 'F'
    if (c >= 'A' && c <= 'F') {
        return (char)(c - 'A' + 10);
    }
    // Invalid character: return maximum char value as sentinel
    return Character.MAX_VALUE;
}

