public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Negative input: " + n);
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Factorial result exceeds long range");
        }
        result *= i;
    }
    return result;
}

