    }

    try {
        // If the search start and stop are equal, simply return a circulator at stop
        if (start == stop) {
            return new OuterFaceCirculator(stop);
        }

        Node current = start;
        // First evaluate the start node itself
        while (true) {
            if (predicate.test(current)) {
                return new OuterFaceCirculator(current);
            }
            if (current == stop) {
                return new OuterFaceCirculator(stop);
            }

            // Move to the next node based on direction
            current = (dir >= 0) ? current.next() : current.prev();

            // Safety check: if the structure is broken or we reach a null reference
            if (current == null) {
                return new OuterFaceCirculator(stop);
            }

            // If we looped back to the start without finding a match, terminate
            if (current == start) {
                return new OuterFaceCirculator(stop);
            }
        }
    } catch (Exception e) {
        // In case of any runtime problems, return a circulator pointing to the stop node
        return new OuterFaceCirculator(stop);
    }
}

