private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.trim().isEmpty()) {
        throw new IllegalStateException("Model name cannot be null or empty");
    }
    Class<?> cls;
    try {
        cls = Class.forName(modelName);
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    }
    java.lang.reflect.Field[] fields = cls.getDeclaredFields();
    java.util.List<Integer> indices = new java.util.ArrayList<>();
    for (java.lang.reflect.Field field : fields) {
        for (java.lang.annotation.Annotation ann : field.getAnnotations()) {
            String annName = ann.annotationType().getName();
            if ("com.example.ShardingKey".equals(annName)) {
                try {
                    java.lang.reflect.Method indexMethod = ann.annotationType().getMethod("index");
                    int idx = (int) indexMethod.invoke(ann);
                    indices.add(idx);
                } catch (Exception ignored) {
                }
            }
        }
    }
    if (indices.isEmpty()) {
        return;
    }
    java.util.Collections.sort(indices);
    int expected = 0;
    for (int idx : indices) {
        if (idx != expected) {
            throw new IllegalStateException("Sharding key indices are not continuous for model " + modelName +
                    ". Expected continuous indices starting from 0 but found index " + idx + " after " + expected + " keys.");
        }
        expected++;
    }
}

