    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return; // nothing to do
    }

    // Obtain the destination bucket (label 0). Create it if it does not exist.
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new java.util.HashSet<>();
        bucketsByLabel.set(0, dest);
    }

    // Update labels for all vertices moved to bucket 0
    for (Integer v : source) {
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        } else {
            // If vertex index is invalid, skip updating its label.
            // Alternatively, you could throw an exception if such behaviour is unacceptable.
        }
    }

    // Merge vertices into bucket 0 and clear the source bucket.
    dest.addAll(source);
    source.clear();
}

