        return 0;
    }
    int count = 0;
    int index = 0;
    try {
        while ((index = str.indexOf(sub, index)) != -1) {
            count++;
            // Move one step forward to allow for overlapping occurrences
            index++;
        }
    } catch (IndexOutOfBoundsException | NullPointerException e) {
        // Return 0 in case of unexpected runtime problems
        return 0;
    }
    return count;
}

