private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        // Node must not be null; return false or throw exception.
        return false;
    }

    // Obtain references to previous and next nodes
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        // Bypass the node from previous node's next reference
        prev.next = next;
    } else {
        // Node was the first element
        this.first = next;
    }

    if (next != null) {
        // Bypass the node from next node's prev reference
        next.prev = prev;
    } else {
        // Node was the last element
        this.last = prev;
    }

    // Clean up the removed node's references
    node.prev = null;
    node.next = null;

    // Decrement size counter if list maintains one
    if (this.size > 0) {
        this.size--;
    }

    return true;
}

