public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int sepIdx = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int fileNameStart = sepIdx + 1;
    if (fileNameStart >= path.length()) {
        return null;
    }
    int dotIdx = path.lastIndexOf('.');
    if (dotIdx <= fileNameStart || dotIdx == path.length() - 1) {
        return null;
    }
    return path.substring(0, dotIdx);
}

