private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Validate input
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list must not be null");
    }

    int n = bounds.size();
    // Prepare a mutable list of the same size to hold suffix sums
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }

    long suffixSum = 0L;
    // Compute suffix sums starting from the end of the list
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        suffixSum += val;
        // Casting to int to match the return type; overflow will wrap as per Java specs
        suffix.set(i, (int) suffixSum);
    }

    // Return the suffix list and the total sum as a Pair
    return new Pair<>(suffix, suffixSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be <= to index");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    /* Move every node from *list* into *this*.  This is implemented by
     * splicing the two internal node chains together in constant time.
     * The implementation assumes that the internal fields of the
     * DoublyLinkedList are:
     *   - firstNode (the first real node, or null if the list is empty)
     *   - lastNode  (the last real node, or null if the list is empty)
     *   - nodeCount (number of nodes in the list)
     *   - ListNodeImpl<E> has public fields 'prev' and 'next'.
     *
     *  If *list* is null, the same instance, or empty this method
     *  simply returns.  All manipulations are guarded by a small
     *  try/catch to convert unexpected exceptions into a RuntimeException
     *  with a helpful message.
     */
    if (list == null || list == this) {
        return;
    }

    try {
        // Source list first and last nodes
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcFirst = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .get(list);
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcLast = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .get(list);

        if (srcFirst == null) {          // source list empty
            return;
        }

        // Destination list fields
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> destFirst = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .get(this);
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> destLast = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .get(this);
        int srcSize = (int) java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .getInt(list);
        int destSize = (int) java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .getInt(this);

        /* Splice source list after destination tail if destination is
         * non-empty; otherwise make source the new list. */
        if (destLast != null) {
            destLast.next = srcFirst;
            srcFirst.prev = destLast;
            destLast = srcLast;
        } else {
            destFirst = srcFirst;
            destLast = srcLast;
        }

        // Update destination list fields
        java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .set(this, destFirst);
        java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .set(this, destLast);
        java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .setInt(this, destSize + srcSize);

        // Clear source list
        java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .set(list, null);
        java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .set(list, null);
        java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .setInt(list, 0);
    } catch (Exception e) {
        throw new RuntimeException("Unable to move list nodes", e);
    }
}

