public static Character toCharacterObject(final char ch) {
    // Cache for ASCII 7-bit characters (0-127)
    // This array is lazily initialized on first use to avoid unnecessary allocation.
    // Using a static inner class ensures thread-safe lazy initialization.
    final class CacheHolder {
        static final Character[] CACHE = createCache();
        private static Character[] createCache() {
            Character[] arr = new Character[128];
            for (int i = 0; i < 128; i++) {
                // Autoboxing creates a new Character instance on each iteration
                // and stores it. These objects can be safely reused because
                // they are immutable.
                arr[i] = (char) i;
            }
            return arr;
        }
    }

    if (ch < 128) {
        return CacheHolder.CACHE[ch];
    } else {
        // For non-ASCII characters no caching; create a new instance on each call.
        return new Character(ch);
    }
}

