private void addReverse(final File[] files){
    // Return immediately if the input array is null or empty
    if (files == null || files.length == 0) {
        return;
    }

    // Ensure the internal collection exists; assume a field named fileList exists
    try {
        if (fileList == null) {
            fileList = new java.util.ArrayList<>();
        }
    } catch (Exception initEx) {
        // If we cannot initialize the collection, log and exit
        System.err.println("Unable to initialize internal file list: " + initEx.getMessage());
        return;
    }

    // Add files in reverse order, skipping any null entries
    for (int i = files.length - 1; i >= 0; i--) {
        File f = files[i];
        if (f == null) {
            continue; // Skip null files
        }
        try {
