private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Validate arguments
    if (graph == null) {
        throw new NullPointerException("Graph must not be null");
    }
    if (vertices == null) {
        throw new NullPointerException("Vertices set must not be null");
    }

    // An empty set or a single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Check that every pair of distinct vertices is connected by an edge
    for (V v : vertices) {
        for (V u : vertices) {
            if (!v.equals(u)) {
                try {
                    // For undirected graphs, getEdge returns the same edge regardless of order
                    if (graph.getEdge(v, u) == null) {
                        return false;
                    }
                } catch (IllegalArgumentException | NullPointerException e) {
                    // If the graph implementation throws for invalid vertices, treat as not a clique
                    return false;
                }
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    for (int i = 0; i < keys.size(); i++){
        K current = keys.get(i);
        int maxLess = Integer.MIN_VALUE; // sentinel for no lower bound found
        boolean found = false;
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> compCurrent = (Comparable<Object>)current;
            for (int j = 0; j < keys.size(); j++){
                if (i == j) continue;
                Object other = keys.get(j);
                try {
                    @SuppressWarnings("unchecked")
                    Comparable<Object> compOther = (Comparable<Object>)other;
                    if (compOther.compareTo(current) < 0){
                        if (!found || (int)compOther > maxLess){
                            maxLess = (int)compOther;
                            found = true;
                        }
                    }
                } catch (ClassCastException | ClassCastException ce){
                    // if other is not comparable, skip it
                }
            }
        } catch (ClassCastException e){
            // current is not comparable; treat as no lower bound
        }
        result.add(found ? maxLess : Integer.MIN_VALUE);
    }
    return result;
}

