private List<Integer> computeUpperBounds(List<K> keys){
    // Validate input
    if (keys == null) {
        throw new IllegalArgumentException("The list of keys cannot be null.");
    }

    List<Integer> bounds = new ArrayList<>(keys.size());
    if (keys.isEmpty()) {
        return bounds; // return empty list for empty input
    }

    // Ensure every key is an Integer
    for (K key : keys) {
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("All keys must be instances of Integer.");
        }
    }

    // Prepare a sorted copy of the keys
    List<Integer> sortedKeys = new ArrayList<>(keys.size());
    for (K key : keys) {
        sortedKeys.add((Integer) key);
    }
    Collections.sort(sortedKeys);

    // Create a map that keeps track of the sorted indices for each key value
    Map<Integer, Queue<Integer>> indexQueue = new HashMap<>();
    for (int i = 0; i < sortedKeys.size(); i++) {
        int value = sortedKeys.get(i);
        indexQueue.computeIfAbsent(value, v -> new LinkedList<>()).add(i);
    }

    // Determine upper bound for each original key
    for (K key : keys) {
        int value = (Integer) key;
        int currentIdx = indexQueue.get(value).poll();   // remove one index
        int upperIdx = currentIdx + 1;
        if (upperIdx < sortedKeys.size()) {
            bounds.add(sortedKeys.get(upperIdx));
        } else {
            // If there's no larger key, use Integer.MAX_VALUE as an "infinite" upper bound
            bounds.add(Integer.MAX_VALUE);
        }
    }

    return bounds;
}

