static String[] toNoNullStringArray(Object[] array){
    // Handle null input
    if (array == null) {
        return new String[0];
    }

    int length = array.length;
    int nullCount = 0;

    // Count nulls
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }

    // No nulls – return original if it is already a String[].  
    if (nullCount == 0) {
        if (array.getClass().getComponentType() == String.class) {
            return (String[]) array;
        } else {
            // Convert all elements to String (unlikely but safe)
            String[] result = new String[length];
            for (int i = 0; i < length; i++) {
                result[i] = array[i].toString();
            }
            return result;
        }
    }

    // Build a new array without nulls
    String[] clean = new String[length - nullCount];
    int dest = 0;
    for (Object obj : array) {
        if (obj != null) {
            clean[dest++] = obj instanceof String ? (String) obj : obj.toString();
        }
    }
    return clean;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int extPos = filename.lastIndexOf('.');
    if (extPos == -1) {
        return -1;
    }
    int slashPos = filename.lastIndexOf('/');
    int backslashPos = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(slashPos, backslashPos);
    return (extPos > lastSeparator ? extPos : -1);
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if(expiredThreshold < 0){
        throw new IllegalArgumentException("expiredThreshold must be non-negative");
    }
    long currentTime = System.currentTimeMillis();
    return (currentTime - timestamp) > expiredThreshold;
}

Edge edgeToNext() {
    try {
        // Ensure that we have both the previous and next nodes.
        if (prev == null) {
            throw new IllegalStateException("Previous node is not available for edge construction");
        }
        if (next == null) {
            throw new IllegalStateException("Next node is not available for edge construction");
        }

        // Resolve potential virtual nodes to their real counterparts.
        Node src = prev.isVirtual() ? prev.getReal() : prev;
        Node dst = next.isVirtual() ? next.getReal() : next;

        // Retrieve the edge connecting the two nodes.
        Edge edge = graph.getEdge(src, dst);
        if (edge == null) {
            throw new IllegalArgumentException(
                "No edge exists between nodes " + src + " and " + dst
            );
        }

        return edge;

    } catch (Exception e) {
        // Wrap any exception in a runtime exception to preserve stack trace.
        throw new RuntimeException("Failed to retrieve edge to next node", e);
    }
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        throw new IllegalArgumentException("Arguments 'str' and 'substring' must not be null.");
    }
    if (index < 0) {
        return false;
    }
    int subLen = substring.length();
    for (int i = 0; i < subLen; i++) {
        int idx = index + i;
        if (idx >= str.length()) {
            return false;
        }
        if (str.charAt(idx) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event){
    if(event == null){
        return;
    }
    String msg;
    try{
        msg = (layout != null) ? layout.format(event) : event.getRenderedMessage();
    }catch(Exception e){
        msg = event.getRenderedMessage();
    }
    if(clients == null || clients.isEmpty()){
        return;
    }
    java.util.List<java.io.PrintWriter> toRemove = new java.util.ArrayList<>();
    synchronized (clients){
        for(java.io.PrintWriter pw : clients){
            try{
                pw.println(msg);
                pw.flush();
            }catch(Exception e){
                toRemove.add(pw);
                e.printStackTrace();
            }
        }
        clients.removeAll(toRemove);
    }
}

public static String toString(final char ch){
    // Outside 7‑bit ASCII range – just create a new String
    if (ch < 0 || ch > 127) {
        return String.valueOf(ch);
    }
    // Try the cache first
    String cached = cache[ch];
    if (cached == null) {
        // Lazily initialize the cache entry in a thread‑safe manner
        synchronized (CharUtils.class) {
            cached = cache[ch];
            if (cached == null) {
                cached = String.valueOf(ch);
                cache[ch] = cached;
            }
        }
    }
    return cached;
}

private void checkIfPackedField() throws IOException {
    // The current tag encodes both the field number and the wire type.
    // Extract them for checking packed-ness.
    int wireType    = tag & 0x07;          // lower 3 bits = wire type
    int fieldNumber = tag >>> 3;           // upper bits = field number

    // Packed repeated fields are encoded as length‑delimited (wire type 2).
    // We only need to act when we encounter such a field.
    if (wireType == 2) {
        // Read the size of the packed payload in bytes.
        int packedSize = readVarint32();

        // Remember that we are now inside a packed field.
        this.packedFieldNumber   = fieldNumber;
        this.currentPackedSize   = packedSize;
        this.packedBytesRemaining = packedSize;
        this.isReadingPacked     = true;

        // Adjust the input limit so that we do not read past the packed field payload.
        // This assumes that `limit` holds the current absolute limit, and
        // `setLimit(int)` will update the effective limit when parsing.
        setLimit(limit - packedSize);
    }
}

public int readTag() throws IOException {
    try {
        int tag = readRawVarint32();
        // In protobuf, tag 0 is not valid and used to signal end-of-message.
        return tag;
    } catch (EOFException e) {
        // Reached end‑of‑file before a tag could be read.
        return 0;
    }
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    // Validate byte ranges (-128 to 127)
    if (byteValue1 < -128 || byteValue1 > 127) {
        throw new IllegalArgumentException("byteValue1 out of range: " + byteValue1);
    }
    if (byteValue2 < -128 || byteValue2 > 127) {
        throw new IllegalArgumentException("byteValue2 out of range: " + byteValue2);
    }

    // Ensure underlying byte array exists
    if (buf == null) {
        buf = new byte[2];
    }

    // Ensure capacity for two more bytes
    if (pos + 2 > buf.length) {
        int newCap = buf.length == 0 ? 2 : buf.length * 2;
        if (newCap < pos + 2) {
            newCap = pos + 2;
        }
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }

    // Append the two bytes
    buf[pos++] = (byte) byteValue1;
    buf[pos++] = (byte) byteValue2;

    return this;
}

private String buildContentRange() {
    // Fields that should be defined in the surrounding class:
    //   long startByte;   // inclusive start of the range
    //   long endByte;     // inclusive end of the range
    //   long totalBytes;  // total length of the resource; may be 0 if unknown
    try {
        if (startByte < 0 || endByte < startByte) {
            throw new IllegalStateException(
                "Invalid byte range: start=" + startByte + ", end=" + endByte);
        }
        // If totalBytes is unknown or zero, use '*' to indicate unknown size
        String range = "bytes " + startByte + "-" + endByte
                       + (totalBytes > 0 ? "/" + totalBytes : "/*");
        return range;
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception so callers are aware
        throw new IllegalStateException("Failed to build Content-Range header", e);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IOException("Provided file is null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    List<ThreadSnapshot> snapshots = new java.util.ArrayList<>();
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty()) {
                continue;
            }
            try {
                // Attempt to create a ThreadSnapshot instance from a line of text.
                // The exact parsing logic depends on the ThreadSnapshot implementation.
                // Commonly it might expose a static factory method like `fromString`.
                ThreadSnapshot snapshot = ThreadSnapshot.fromString(line);
                // Retrieve the snapshot's timestamp. The method name may vary
                // (e.g., getTimestamp, getTime, getStartTime). Adjust if necessary.
                long snapshotTime = snapshot.getTimestamp();
                boolean inRange = false;
                if (timeRanges != null) {
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        // Assume range has getStartTime() and getEndTime() that return long timestamps.
                        if (snapshotTime >= range.getStartTime() && snapshotTime <= range.getEndTime()) {
                            inRange = true;
                            break;
                        }
                    }
                }
                if (inRange) {
                    snapshots.add(snapshot);
                }
            } catch (Exception e) {
                // If the line cannot be parsed into a snapshot, skip it silently.
                // Logging could be added here if desired.
            }
        }
    }
    return snapshots;
}
